'use strict';
const D=window.COMPASS_DATA;
const state={view:'plan',territory:'SP',capacity:6,selected:new Set(),deferred:new Set(),events:[],approved:false,query:'',filter:'all',limit:30};
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:0,maximumFractionDigits:0}).format(n);
const pct=n=>Math.round(n*100)+'%';
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Not available';
const title=s=>String(s).replaceAll('_',' ').replace(/[\p{L}\p{M}]+/gu,w=>w[0].toUpperCase()+w.slice(1).toLowerCase());
const find=id=>D.accounts.find(a=>a.id===id);
const planningPolicy=()=>window.CompassRep?.getPlanningPolicy()||window.CompassPriority.defaults;
const priorityFor=a=>window.CompassPriority.assess(a,D.asof,planningPolicy());
const comparePriority=(a,b)=>priorityFor(b).score-priorityFor(a).score||a.id.localeCompare(b.id);
const annualRisk=a=>priorityFor(a).annualValueAtRisk;
const annualValue=a=>a.baseline*12;
const scoreText=n=>Math.round(n).toLocaleString('en-GB');
const weightText=n=>Number(n.toFixed(2));
const adviceFor=a=>{const planning=priorityFor(a),inputs=window.CompassPriority.adviceInputs(a,window.COMPASS_CONTEXT||{},planning,D.asof);return {...window.CompassCommercial.build(inputs.account,inputs.context,window.CompassRep?.getOfferPolicy()||window.CompassCommercial.defaults,window.CompassRep?.getOfferInput(a.id)||{}),planning};};
function priorityHtml(a,detail=false){const p=priorityFor(a);return `<section class="ranking-summary ${detail?'ranking-detail':''}"><div class="row"><strong>Planning score ${scoreText(p.score)}</strong><span class="weight-tag">×${weightText(p.weight)} actionability</span></div>${detail?p.reasons.map(r=>`<p>${esc(r)}</p>`).join(''):`<span class="sub">${esc(p.signals.length?p.signals[0].label:'Standard issue weight')}${p.overdue?' · long-silence adjustment':''}</span>`}${detail?'<p class="notice">Planning score = annualised value at risk × editable actionability weight. These weights are assumptions, not measured save probabilities. Annualised exposure is 12× monthly exposure at the historical spending rate; risk still concerns inactivity in the next 90 days. It is not a 12-month forecast or guaranteed recoverable revenue.</p>':''}</section>`;}
const scope=()=>D.accounts.filter(a=>state.territory==='ALL'||a.state===state.territory);
const eligible=()=>scope().filter(a=>a.recency<90&&!state.deferred.has(a.id)&&!state.events.some(e=>e.id===a.id)).sort(comparePriority);
const selected=()=>D.accounts.filter(a=>state.selected.has(a.id)).sort(comparePriority);
function propose(){state.selected=new Set(eligible().slice(0,Math.min(state.capacity,20-state.events.length)).map(a=>a.id));state.approved=false;}
function badge(a){return `<span class="risk ${a.risk<.3?'low':a.risk<.5?'mid':''}">${pct(a.risk)}</span>`;}
function rationale(a){
  if(a.reasons.includes('Delivery friction')||a.reasons.includes('Low recent review'))return 'Resolve service friction before discussing a reorder.';
  if(a.reasons.includes('Regular category missing'))return 'Ask why a regular product line disappeared; discuss a basket-based reorder.';
  if(a.reasons.includes('Cadence broken'))return 'Check the missed replenishment rhythm and agree a next-order date.';
  if(a.reasons.includes('Orders declining'))return 'Understand falling purchase frequency before suggesting an offer.';
  return 'Confirm the account’s current buying needs and next replenishment date.';
}
function evidence(a){return `${a.orders_previous} → ${a.orders_recent} orders / 90 days · ${Math.round(a.recency)} days since last order`}
function controls(){return `<div class="toolbar"><label for="territory">Territory</label><select id="territory">${['ALL',...new Set(D.accounts.map(a=>a.state))].sort().map(s=>`<option value="${esc(s)}" ${s===state.territory?'selected':''}>${s==='ALL'?'All states':esc(s)}</option>`).join('')}</select><label for="capacity">Contact slots this week</label><input id="capacity" type="number" min="1" max="20" value="${state.capacity}" ${state.approved?'disabled':''}><button class="button small" id="replan">Propose plan</button></div>`;}
function accountRows(accounts,selectable=false){return accounts.map((a,i)=>`<tr>${selectable?`<td><input type="checkbox" data-select="${a.id}" ${state.selected.has(a.id)?'checked':''} ${state.approved?'disabled':''} aria-label="Select ${a.id}"></td>`:''}<td><button class="account-name" data-account="${a.id}">${esc(a.id)}</button><span class="sub">${esc(title(a.city))}, ${esc(a.state)}</span></td><td>${badge(a)}<span class="sub">90-day inactivity</span></td><td><strong>${money(annualValue(a))}</strong><span class="sub">Annual account value</span></td><td><strong>${money(annualRisk(a))}</strong><span class="sub">Annualised · risk × value</span></td><td><strong>${scoreText(priorityFor(a).score)}</strong><span class="sub">×${weightText(priorityFor(a).weight)} actionability</span></td><td>${a.reasons.slice(0,2).map(r=>`<span class="tag ${r==='Delivery friction'||r==='Low recent review'?'warn':''}">${esc(r)}</span>`).join('')}<span class="sub">${esc(evidence(a))}</span></td>${selectable?`<td><button class="button small" data-defer="${a.id}" ${state.approved?'disabled':''}>Not this week</button></td>`:''}</tr>`).join('')}
function table(accounts,selectable=false){if(!accounts.length)return '<div class="empty"><h3>No accounts in this group</h3><p class="muted">Try another territory or a different filter.</p></div>';return `<div class="table-wrap"><table><thead><tr>${selectable?'<th>Select</th>':''}<th>Account</th><th>Risk</th><th>Annual account value</th><th>Annual value at risk</th><th>Planning score</th><th>What changed</th>${selectable?'<th>Plan</th>':''}</tr></thead><tbody>${accountRows(accounts,selectable)}</tbody></table></div>`;}
function renderPlan(){
 const list=selected(),pool=eligible(),monitor=pool.filter(a=>!state.selected.has(a.id)).slice(0,4);
 const inactive=scope().filter(a=>a.recency>=90).length;
 const deferred=scope().filter(a=>state.deferred.has(a.id)).sort((a,b)=>Number(state.deferred.has(b.id))-Number(state.deferred.has(a.id))).slice(0,4);
 const total=list.reduce((s,a)=>s+annualRisk(a),0),service=list.filter(a=>a.reasons.includes('Delivery friction')||a.reasons.includes('Low recent review')).length;
 return `<div class="topline"><div><p class="eyebrow">WEEK OF 3–7 SEPTEMBER 2018</p><h1>Your next best<br>conversations.</h1><p class="muted">A focused retention plan for ${state.territory==='ALL'?'all territories':esc(state.territory)}.</p></div><button class="button primary" id="approve" ${!list.length||state.approved?'disabled':''}>${state.approved?'Plan approved':`Approve ${list.length} contacts`}</button></div>${controls()}<div class="stats"><div class="stat"><strong>${pool.length}</strong><span>Prevention candidates</span></div><div class="stat"><strong>${list.length} / ${state.capacity}</strong><span>Proposed contact slots</span></div><div class="stat"><strong>${money(total)}</strong><span>Annualised value at risk in plan</span></div></div><section class="brief"><div><p class="eyebrow">AGENT BRIEF · EVIDENCE-BASED SIMULATION</p><h2>${state.approved?'Your plan is on the agenda.':'Protect value before the next missed order.'}</h2><p>${list.length?`Start with ${esc(list[0].id)}: ${rationale(list[0])} This plan covers ${list.length} prevention candidates ranked by annualised value at risk × actionability. ${service?`${service} ${service===1?'account needs':'accounts need'} a service-recovery conversation.`:''}`:'There are no eligible contacts for the current settings.'}</p><p>${inactive} accounts are already 90+ days inactive and belong in a separate win-back queue, not this prevention plan.</p><div class="meta">No autonomous outreach. Your approval creates in-app appointments only. Recommendations are hypotheses, not confirmed causes.</div></div><div><button class="button lime" id="open-agenda">${state.approved?'Open agenda':'Review account evidence'}</button></div></section><section class="panel"><div class="row"><h2>${state.approved?'Approved contacts':'Prioritise this week'}</h2><span class="muted">${list.length} conversations</span></div>${table(list,true)}</section><div class="grid2"><section class="panel"><h2>Monitor, don’t crowd the agenda</h2><p class="muted">Lower planning priority or outside this week’s capacity. Reassess next week.</p>${monitor.map(a=>`<div class="row" style="padding:11px 0;border-top:1px solid var(--line)"><div><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${pct(a.risk)} risk · ${money(annualRisk(a))} exposed</span></div><button class="button small" data-add="${a.id}" ${state.approved||list.length>=state.capacity?'disabled':''}>Add to plan</button></div>`).join('')||'<p>No additional accounts to monitor.</p>'}</section><section class="panel"><h2>Deprioritise this week</h2><p class="muted">Keep these accounts visible without using a prevention slot.</p>${deferred.map(a=>`<p><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${'Deferred by rep for this session.'}</span></p>`).join('')||'<p class="muted">Use “Not this week” to move an account here.</p>'}<p class="notice">Accounts already scheduled are suppressed from new proposals. Small / new accounts are excluded from model scoring because their history is insufficient.</p></section></div>`;
}
function renderAccounts(){
 let accounts=scope().filter(a=>(state.filter==='all'||(state.filter==='inactive'?a.recency>=90:a.recency<90))&&`${a.id} ${a.city} ${a.reasons.join(' ')}`.toLowerCase().includes(state.query.toLowerCase())).sort(comparePriority);
 return `<div class="topline"><div><p class="eyebrow">ACCOUNT WATCHLIST</p><h1>Every warning.<br>With the evidence.</h1><p class="muted">${D.eligible_accounts.toLocaleString()} established accounts scored as of 31 August 2018.</p></div></div><div class="toolbar"><label for="territory">Territory</label><select id="territory">${['ALL',...new Set(D.accounts.map(a=>a.state))].sort().map(s=>`<option ${s===state.territory?'selected':''} value="${s}">${s==='ALL'?'All states':s}</option>`).join('')}</select><input type="search" id="search" placeholder="Account, city or warning" aria-label="Search accounts" value="${esc(state.query)}"><select id="filter" aria-label="Account status">${[['all','All scored accounts'],['prevention','Prevention candidates'],['inactive','90+ days inactive']].map(([v,l])=>`<option value="${v}" ${state.filter===v?'selected':''}>${l}</option>`).join('')}</select><span class="muted">${accounts.length} accounts</span></div><section class="panel">${table(accounts.slice(0,state.limit))}${accounts.length>state.limit?'<button class="button" id="more">Show 30 more</button>':''}</section>`;
}
function renderAgenda(){
 if(!state.events.length)return `<p class="eyebrow">YOUR AGENDA</p><h1>A plan becomes<br>a conversation.</h1><div class="empty"><h2>No appointments yet</h2><p class="muted">Review and approve a weekly plan to schedule contacts with their briefs attached.</p><button class="button primary" id="back-plan">Review weekly plan</button></div>`;
 return `<div class="topline"><div><p class="eyebrow">APPROVED PLAN · 3–7 SEPTEMBER 2018</p><h1>Your week,<br>ready to act.</h1><p class="muted">${state.events.filter(e=>e.status==='Planned').length} planned contacts · ${state.events.filter(e=>e.status!=='Planned').length} outcomes recorded</p></div><button class="button primary" id="export-calendar">Download calendar (.ics)</button></div><p class="notice">Demo appointments and outcomes are session-only. Download the calendar before leaving. Nothing is sent to customers or your real calendar.</p><div class="agenda-grid">${D.week.map((d,i)=>`<section class="day"><h3>${['Monday','Tuesday','Wednesday','Thursday','Friday'][i]}</h3><span class="sub">${date(d)}</span>${state.events.filter(e=>e.date===d).map(e=>{const a=find(e.id);return `<article class="event ${e.status!=='Planned'?'done':''}"><time>${e.time} · 30-minute call</time><p><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${esc(title(a.city))}, ${a.state}</span></p><p>${rationale(a)}</p><select data-outcome="${e.id}" aria-label="Outcome for ${e.id}">${['Planned','Contacted','No answer','Issue resolved','Follow-up agreed'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select><input data-note="${e.id}" value="${esc(e.note)}" placeholder="Agreed next step" aria-label="Next step for ${e.id}"><label class="sub" for="follow-${e.id}">Follow-up date</label><input id="follow-${e.id}" data-follow="${e.id}" type="date" min="2018-09-03" value="${e.follow||''}"><button class="button small" data-account="${e.id}" style="margin-top:8px">Open contact brief</button></article>`}).join('')||'<p class="notice">No contacts scheduled.</p>'}</section>`).join('')}</div>${state.events.some(e=>e.follow)?`<section class="panel"><h2>Follow-up queue</h2>${state.events.filter(e=>e.follow).sort((a,b)=>a.follow.localeCompare(b.follow)).map(e=>`<p><button class="account-name" data-account="${e.id}">${e.id}</button> · ${date(e.follow)} <span class="muted">${esc(e.note||'Confirm the agreed next step')}</span></p>`).join('')}</section>`:''}`;
}
function renderModel(){const m=D.metrics;return `<p class="eyebrow">REAL MODEL · SIMULATED AGENT</p><h1>Evidence you<br>can inspect.</h1><div class="stats"><div class="stat"><strong>${m.auc.toFixed(2)}</strong><span>Exploratory test ROC-AUC</span></div><div class="stat"><strong>${pct(m.top10_precision)}</strong><span>Inactivity rate in highest-risk 10%</span></div><div class="stat"><strong>${m.top10_lift.toFixed(1)}×</strong><span>Top-decile lift vs test average</span></div></div><div class="grid2 method"><section class="panel"><h2>What the engine predicts</h2><p>Probability that an established account makes no product-backed purchase in the next 90 days. A purchase has at least one recorded product line; final fulfillment status is not used because its historical changes are unavailable.</p><p>Eligibility: at least 10 purchases and 180 days of history at the snapshot date. The public demo uses zip-code account areas, not real individual outlets.</p><h3>Core inputs</h3><ul><li>Recency and the account’s median order interval</li><li>Recency relative to the usual order interval</li><li>Recent and previous 90-day purchase counts and their relative change</li></ul><p>Delivery, review and category-gap evidence guide actionability weights and the simulated brief; the selected prediction model uses purchase patterns. Four feature sets were compared on the February validation snapshot; the six-feature model had the highest AUC (0.722).</p></section><section class="panel"><h2>Chronological validation</h2><ul><li><strong>Train:</strong> September–November 2017 snapshots; labels fully observed by 28 February 2018 (${m.train_n.toLocaleString()} rows).</li><li><strong>Select + calibrate:</strong> 28 February 2018 snapshot; outcomes through 29 May (${m.calibration_n.toLocaleString()} accounts).</li><li><strong>Test:</strong> 31 May 2018 snapshot; outcomes through 29 August (${m.n.toLocaleString()} accounts).</li><li><strong>Score:</strong> 31 August 2018, using the same frozen model and calibration.</li></ul><p>Deliveries and reviews appear only after their actual timestamps. Outcome windows do not cross the train/calibration/test boundaries. Repeated accounts across periods reflect the intended existing-account deployment.</p><p>Test average inactivity: ${pct(m.base_rate)} · Brier score: ${m.brier.toFixed(3)} · Recency-only AUC: ${m.recency_auc.toFixed(2)} · Cadence-only AUC: ${m.cadence_auc.toFixed(2)}.</p><p class="notice">Exploratory results, not a blind final test: the May snapshot was inspected during development. Recency alone slightly outperforms this model on May AUC. A new unseen period and probability-calibration checks are required before operational use. Top-decile metrics describe the full eligible test cohort, not this week’s filtered prevention plan.</p></section></div><section class="panel method"><h2>How priority differs from risk</h2><p><strong>Annualised value at risk = predicted inactivity risk × baseline monthly spend.</strong> The baseline comes from days 91–180 before the snapshot, so a recent decline does not erase the account’s value. If that window has no spend, use the last 180-day monthly average. Values are shown in Brazilian reais (R$). Annualisation assumes the historical monthly spending rate continues for 12 months. The probability remains a 90-day inactivity prediction. Value at risk is not profit, a yearly churn forecast or guaranteed recoverable revenue.</p><p>The prevention queue includes all scored accounts with a purchase in the last 90 days, with no minimum risk cutoff. Territory and rep capacity determine the contact list. Planning score = annualised value at risk × an editable actionability weight. Apply the issue boost once for an average recent rating ≤2/5, a known late delivery on recent purchases, or a missing regular product line. Apply the long-silence weight when recency exceeds the configured multiple of normal order cadence; both adjustments can combine. The top 30% by planning score are considered for visits, subject to reach, days and travel time. Visit order balances planning score per meeting-and-travel minute. These are planning assumptions, not estimated intervention effects.</p></section><section class="panel method"><h2>What is real, and what is simulated?</h2><p>Real: source records, derived account histories, trained penalised logistic regression, calibrated scores, historical validation. Rule-based: actionability weights and ranked priorities, agent wording, visit-versus-call decisions, suggested actions and geographic scheduling. Maps, optional road-route estimates and on-demand machine translation use real services. Agenda approval, outcome capture, follow-up dates and calendar export work in the browser.</p><p>No LLM or live CRM/calendar is connected. Agenda and outcomes reset on reload; rep preferences are stored on this browser. Published review excerpts are filtered for contact information and identifiers. There are no personal customer identifiers or API secrets in the app. Risk estimates are preliminary: zip-area aggregation, limited history, business growth and seasonality constrain transfer to real outlets. Intervention success is not estimated.</p></section><section class="panel method"><h2>Travel and customer comments</h2><p>Coordinates represent postal-area centres, and rep bases are median city coordinates. Radius means straight-line distance from base, not road kilometres. Every visit day returns to base. Working hours, visit duration and visit days are chosen by the rep; calls take 30 minutes and lunch is reserved 12:00–13:00.</p><p>Car routing uses the <a href="https://project-osrm.org/docs/v26.5.0/http" target="_blank" rel="noopener">OSRM public demo service</a> when available, without live traffic: route durations receive a 20% buffer plus ten minutes per leg. If unavailable, estimates use distance × 1.35 at 35 km/h plus ten minutes. Transit uses distance × 1.45 at 22 km/h plus fifteen minutes; this is not a timetable or a verified transit itinerary. Road shapes are solid; geographic connections are dashed. The free service is for a low-volume challenge demo.</p><p>Comments are dated Portuguese excerpts with optional English machine translation through MyMemory. Keyword issue labels describe possible complaints, not verified causes. Issue counts cover safe comments submitted in the last 180 days; known late-delivery counts cover purchases in that period. Originals, dates and scores remain visible. No review submitted after 31 August 2018 appears.</p></section>`;}
function foot(){return `<div class="foot">Historical simulation as of 31 August 2018 · Account areas, not actual bar/shop identities · Browser-session demo · <button class="button small ghost" id="reset">Reset demo</button></div>`;}
function render(){
 $('main').innerHTML=({plan:renderPlan,accounts:renderAccounts,agenda:renderAgenda,model:renderModel,routes:()=>window.CompassRep.renderRoutes(),profile:()=>window.CompassRep.renderProfile()}[state.view])()+foot();
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
 $('agenda-count').textContent=state.events.length;
 bind();
}
function show(view){state.view=view;render();window.scrollTo({top:0,behavior:'smooth'});}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('toast-show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('toast-show'),3500);}
function approve(){
 const s=selected();if(!s.length||s.length>state.capacity)throw new Error('Choose between 1 and '+state.capacity+' contacts.');
 if(state.approved)return;
 const slots=D.week.flatMap(date=>['09:00','10:00','11:00','14:00'].map(time=>({date,time}))).filter(slot=>!state.events.some(e=>e.date===slot.date&&e.time===slot.time));
 if(s.length>slots.length)throw new Error('The demo week is full. Reset or reduce the plan.');
 s.forEach((a,i)=>{if(!state.events.some(e=>e.id===a.id)){state.events.push({id:a.id,...slots[i],status:'Planned',note:'',follow:''});}});
 state.approved=true;render();toast(`${s.length} contact briefs scheduled. Open Agenda to record outcomes.`);
}
function bind(){
 document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>openAccount(b.dataset.account));
 document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{if(b.checked&&state.selected.size>=state.capacity){b.checked=false;toast('Your weekly capacity is full.');return;}b.checked?state.selected.add(b.dataset.select):state.selected.delete(b.dataset.select);render();});
 document.querySelectorAll('[data-defer]').forEach(b=>b.onclick=()=>{state.selected.delete(b.dataset.defer);state.deferred.add(b.dataset.defer);render();toast('Moved to deprioritised for this session.');});
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(state.selected.size<state.capacity)state.selected.add(b.dataset.add);render();});
 if($('territory'))$('territory').onchange=e=>{state.territory=e.target.value;state.limit=30;if(state.view==='plan')propose();render();};
 if($('capacity'))$('capacity').onchange=e=>{state.capacity=Math.max(1,Math.min(20,Math.floor(Number(e.target.value)||6)));propose();render();};
 if($('replan'))$('replan').onclick=()=>{propose();render();toast('Plan refreshed. Scheduled accounts are excluded.');};
 if($('approve'))$('approve').onclick=approve;
 if($('open-agenda'))$('open-agenda').onclick=()=>state.approved?show('agenda'):selected()[0]&&openAccount(selected()[0].id);
 if($('back-plan'))$('back-plan').onclick=()=>show('plan');
 if($('search'))$('search').oninput=e=>{state.query=e.target.value;state.limit=30;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};
 if($('filter'))$('filter').onchange=e=>{state.filter=e.target.value;state.limit=30;render();};
 if($('more'))$('more').onclick=()=>{state.limit+=30;render();};
 document.querySelectorAll('[data-outcome]').forEach(el=>el.onchange=()=>{state.events.find(e=>e.id===el.dataset.outcome).status=el.value;render();toast('Outcome recorded for this session.');});
 document.querySelectorAll('[data-note]').forEach(el=>el.onchange=()=>{state.events.find(e=>e.id===el.dataset.note).note=el.value;render();toast('Next step recorded.');});
 document.querySelectorAll('[data-follow]').forEach(el=>el.onchange=()=>{state.events.find(e=>e.id===el.dataset.follow).follow=el.value;render();toast('Follow-up queue updated.');});
 if($('export-calendar'))$('export-calendar').onclick=exportCalendar;
 $('reset').onclick=()=>{if(window.confirm('Reset the demo plan, appointments and outcomes?')){state.events=[];state.deferred.clear();state.capacity=6;propose();show('plan');toast('Demo reset.');}};
}
function accountActionHtml(a){
 const action=adviceFor(a),c=action.commercial,q=c.preview,b=window.CompassCommercial.brl;
 return `<section class="account-action-brief"><p class="eyebrow">ACTION BRIEF</p><h3>${esc(action.title)}</h3><p class="muted">${esc(action.signal)}</p><h3 class="cause-heading">What could be causing the change?</h3><p class="notice">Historical signals suggest questions to investigate. They do not establish a cause or predict which offer will work.</p><div class="cause-grid">${action.causes.map(cause=>`<article class="cause-card"><span class="cause-status ${cause.id==='price'?'unconfirmed':''}">${esc(cause.status)}</span><h4>${esc(cause.title)}</h4><p>${esc(cause.evidence)}</p><p><strong>Ask:</strong> ${esc(cause.question)}</p><p class="cause-remedy"><strong>Act:</strong> ${esc(cause.remedy)}</p></article>`).join('')}</div><p class="action-label">READY-TO-USE OPENER</p><blockquote class="script">“${esc(action.talkingPoint)}”</blockquote><button class="button small" id="copy-brief">Copy talking point</button><p class="action-label">ASK NEXT</p><ul>${action.questions.map(question=>`<li>${esc(question)}</li>`).join('')}</ul><p class="action-label">POSSIBLE NEXT STEPS</p>${action.steps.map((step,i)=>`<div class="action-item"><strong>${i+1}. ${esc(step.title)}</strong><p>${esc(step.body)}</p></div>`).join('')}<section class="negotiation-plan"><p class="eyebrow">WHEN TALKING ALONE ISN’T ENOUGH</p><h3>A concrete retention proposal</h3><p><strong>Start with the underlying problem.</strong> ${esc(c.remedy)}</p><details><summary>Other remedies to bring to the negotiation</summary>${c.alternatives.map(o=>`<p><strong>${esc(o.title)}</strong><br>${esc(o.body)}<span class="sub">${esc(o.condition)}</span></p>`).join('')}</details><p class="offer-conditional">${esc(c.summary)}</p><form id="offer-form" class="offer-form"><div class="form-grid"><label>Cause confirmed by customer<select id="offer-driver" aria-label="Cause confirmed by customer"><option value="unknown" ${c.inputs.driver==='unknown'?'selected':''}>Not confirmed yet</option>${[['service','Unresolved service issue'],['category','Product mix / availability'],['demand','Demand / excess stock'],['price','Price / competing offer']].map(([id,label])=>`<option value="${id}" ${id===c.inputs.driver?'selected':''}>${label}</option>`).join('')}</select></label><label>Proposed basket (R$)<input id="offer-basket" type="number" min="0.01" max="100000000" step="0.01" value="${c.inputs.basket??''}" required></label><label>Discount (%) · ceiling ${c.policy.maxDiscount}%<input id="offer-rate" type="number" min="0.01" max="${c.policy.maxDiscount}" step="0.01" value="${c.inputs.rate}" required></label><label>Gross margin before offer (%) · optional<input id="offer-margin" type="number" min="0" max="100" step="0.01" value="${c.inputs.margin??''}" placeholder="Unknown in dataset"></label></div><p class="notice">${esc(c.reference.source)}${c.reference.amount!==null?': '+esc(b(c.reference.amount)):''}. This is a reference basket, not a customer commitment. Enter the actual basket and any known margin. Apply changes to refresh the draft.</p><button class="button primary small" type="submit">Update proposal</button><p id="offer-error" class="error" role="alert"></p></form><div class="offer-preview ${q.blocked?'offer-blocked':''}" aria-live="polite"><p class="action-label">${q.blocked?'DRAFT BLOCKED':q.marginKnown?'DEMO DRAFT · COMMERCIAL REVIEW REQUIRED':'DEMO DRAFT · MARGIN REVIEW NEEDED'}</p>${q.discount!==null?`<div class="offer-metrics"><div><strong>${esc(b(q.discount))}</strong><span>One-order discount cost</span></div><div><strong>${esc(b(q.net))}</strong><span>Net basket revenue</span></div><div><strong>${q.effectiveRate}%</strong><span>Effective discount${q.capped?' · capped':''}</span></div></div>${q.marginKnown?`<p>Estimated gross profit: ${esc(b(q.grossProfitBefore))} before → <strong>${esc(b(q.grossProfitAfter))} after</strong>, using the margin entered by the rep; other costs excluded.</p>`:'<p class="notice">Cost and margin are absent from the dataset. A discount cost can be calculated; profitability and retention lift cannot.</p>'}`:''}${q.errors.map(error=>`<p class="error">${esc(error)}</p>`).join('')}<p class="offer-terms">One agreed order only · no stacking · no recurring reduction · actual terms require commercial review.</p></div><p class="action-label">NEGOTIATION TALKING POINT</p><blockquote class="script">“${esc(c.openingPoint)}”</blockquote><div class="action-buttons"><button class="button small" id="copy-offer" ${q.blocked?'disabled':''}>Copy draft proposal</button><button class="button small" id="note-offer" ${q.blocked||!state.events.some(e=>e.id===a.id&&e.type!=='travel')?'disabled':''}>Add draft to agenda note</button></div><p class="notice">Adding a draft records a proposal, not customer acceptance. Agenda notes and confirmed causes stay in this session.</p><p class="action-goal"><strong>Follow through</strong>${esc(c.followUp)}</p></section><p class="action-goal"><strong>Aim to leave with</strong>${esc(action.successCheck)}</p></section>`;
}
function bindActionBrief(a){
 const copy=async(text,message)=>{try{await navigator.clipboard.writeText(text);toast(message);}catch{toast('Clipboard unavailable. Select and copy the text manually.');}};
 $('copy-brief').onclick=()=>copy(adviceFor(a).talkingPoint,'Talking point copied.');
 $('copy-offer').onclick=()=>{const draft=adviceFor(a).commercial.draft;if(draft)copy(draft,'Draft proposal copied.');};
 $('note-offer').onclick=()=>{const draft=adviceFor(a).commercial.draft,event=state.events.find(e=>e.id===a.id&&e.type!=='travel');if(!draft||!event)return;if(!event.note.includes(draft))event.note=[event.note,'Draft offer: '+draft].filter(Boolean).join('\n');render();toast('Draft added to the agenda note.');};
 $('offer-form').querySelectorAll('input,select').forEach(input=>input.oninput=()=>{$('copy-offer').disabled=true;$('note-offer').disabled=true;$('offer-error').textContent='Apply changes with “Update proposal” before using this draft.';});
 $('offer-form').onsubmit=e=>{e.preventDefault();const margin=$('offer-margin').value;const input={driver:$('offer-driver').value,basket:Number($('offer-basket').value),rate:Number($('offer-rate').value),margin:margin===''?null:Number(margin)};
  if(!window.CompassRep){$('offer-error').textContent='Rep settings must load before editing a proposal.';return;}
  window.CompassRep.setOfferInput(a.id,input);$('detail').querySelector('.account-action-brief').outerHTML=accountActionHtml(a);bindActionBrief(a);render();toast('Proposal refreshed; risk ranking is unchanged.');
 };
}
function openAccount(id){
 const a=find(id);if(!a)throw new Error('Unknown account');
 const max=Math.max(1,...a.history.map(h=>h.orders));
 const action=adviceFor(a);
 const evidenceLines=[`Last purchase: ${date(a.last)} (${Math.round(a.recency)} days ago). Usual median purchase interval: ${Math.round(a.cadence)} days.`, `Recent 90 days: ${a.orders_recent} purchases and ${money(a.value_recent)}; previous 90 days: ${a.orders_previous} purchases and ${money(a.value_previous)}.`, `Cadence warning starts after ${Math.round(Math.max(30,2*a.cadence))} days; currently ${a.cadence_ratio.toFixed(1)}× the usual gap.`,a.late_rate!==null?`${pct(a.late_rate)} of known deliveries on recent purchases were late by calendar day.`:'No usable recent delivery evidence.',a.review!==null?`Recent known average review: ${a.review}/5. Latest review in this window: ${date(a.review_date)}.`:'No known reviews submitted in the last 90 days.'];
 $('detail').innerHTML=`<div class="dialog-header"><div><p class="eyebrow" style="color:var(--lime)">ACCOUNT BRIEF · ${a.recency>=90?'WIN-BACK':'PREVENTION CANDIDATE'}</p><h2>${a.id}</h2><p>${esc(title(a.city))}, ${a.state} · ${a.n} historical purchases</p></div><button class="button small" id="close-dialog" aria-label="Close account brief">Close</button></div><div class="dialog-content"><div class="metric-list"><div><strong>${pct(a.risk)}</strong><small>90-day inactivity risk</small></div><div><strong>${money(annualValue(a))}</strong><small>Historical annual account value</small></div><div><strong>${money(annualRisk(a))}</strong><small>Annualised value at risk</small></div></div>${priorityHtml(a,true)}${accountActionHtml(a)}<p class="detail-label">OBSERVED WARNINGS</p>${a.reasons.map(r=>`<span class="tag warn">${esc(r)}</span>`).join('')}<ul>${evidenceLines.map(line=>`<li>${esc(line)}</li>`).join('')}</ul><p class="detail-label">PURCHASE HISTORY · JAN 2017 TO AUG 2018</p><div class="bars" role="img" aria-label="Monthly order counts: ${esc(a.history.map(h=>h.month+': '+h.orders).join(', '))}">${a.history.map(h=>`<div class="bar" style="height:${Math.max(3,h.orders/max*100)}%" data-label="${h.month}: ${h.orders} orders" title="${h.month}: ${h.orders} orders"></div>`).join('')}</div><div class="history-label"><span>Jan 2017</span><span>Aug 2018</span></div>${a.drops.length?`<p class="detail-label">REGULAR CATEGORIES NOW ABSENT</p>${a.drops.map(d=>`<p><strong>${esc(title(d.category))}</strong><span class="sub">${d.previous_orders} purchases in days 91–180; none in the last 90 days. Last purchase ${date(d.last)}.</span></p>`).join('')}`:'<p class="notice">No category met the regular-category gap rule: at least three previous-window purchases and none recently.</p>'}<p class="notice">Area-level demonstration only. Validate against actual account records. No evidence of a specific buyer’s motive. Discuss commercial offers only within approved policies.</p><span class="sub">Annual values: 12× historical monthly baseline from days 91–180 before 31 Aug (180-day fallback when needed)</span></div>`;
 $('close-dialog').onclick=()=>$('detail').close();
 bindActionBrief(a);
 if(!$('detail').open)$('detail').showModal();
}
function icsEscape(s){return String(s).replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');}
function calendarText(){
 let parts=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Account Compass//Retention Demo//EN','CALSCALE:GREGORIAN'];
 const add=(e,follow=false)=>{const a=find(e.id);const day=(follow?e.follow:e.date).replaceAll('-','');const tm=(follow?'10:00':e.time).replace(':','');const finish=tm.slice(0,2)+'30';parts.push('BEGIN:VEVENT',`UID:compass-${e.id}-${follow?'follow':'contact'}-${day}@retention.demo`,'DTSTAMP:20180831T235959Z',`DTSTART:${day}T${tm}00`,`DTEND:${day}T${finish}00`,`SUMMARY:${icsEscape((follow?'Follow-up: ':'Retention call: ')+a.id)}`,`LOCATION:${icsEscape(title(a.city)+', '+a.state)}`,`DESCRIPTION:${icsEscape(`${evidence(a)}. Risk ${pct(a.risk)}. Annualised value at risk ${money(annualRisk(a))}. ${rationale(a)} Outcome: ${e.status}. ${e.note}`)}`,'END:VEVENT');};
 state.events.forEach(e=>{add(e);if(e.follow)add(e,true);});parts.push('END:VCALENDAR');
 const encoder=new TextEncoder();
 return parts.map(line=>{let out='',count=0;for(const char of line){const size=encoder.encode(char).length;if(count+size>75){out+='\r\n ';count=1;}out+=char;count+=size;}return out;}).join('\r\n')+'\r\n';
}
function exportCalendar(){const blob=new Blob([calendarText()],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Account_Compass_Week_2018-09-03.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Calendar downloaded. Historical demo dates; times use your calendar’s local timezone.');}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
$('detail').addEventListener('click',e=>{if(e.target===$('detail')){$('detail').close();}});
propose();render();
// Browser agent tools use exactly the same state and actions as the visible interface.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const tools=[{name:'read_weekly_retention_plan',description:'Read selected contacts, outreach decisions and schedule without modifying the plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({asof:D.asof,approved:state.approved,planningPolicy:planningPolicy(),annualValueBasis:'12 × historical monthly exposure; not a yearly risk forecast',accounts:selected().map(a=>({id:a.id,risk:a.risk,riskHorizonDays:90,annualAccountValue:annualValue(a),annualValueAtRisk:annualRisk(a),monthlyValueExposed:a.exposed,planningScore:priorityFor(a).score,actionabilityWeight:priorityFor(a).weight,rankingReasons:priorityFor(a).reasons,reasons:a.reasons,suggestedAction:adviceFor(a)})),outreach:window.CompassRep?.getPlan()?.decisions||[],schedule:(state.approved?state.events:window.CompassRep?.getPlan()?.events||[]).map(e=>({id:e.id,accountId:e.type==='travel'?(e.accountId||null):e.id,type:e.type,date:e.date,start:e.time,end:e.end}))})},{name:'open_account_brief',description:'Open the existing evidence brief for one scored account; does not schedule or contact it.',inputSchema:{type:'object',properties:{accountId:{type:'string'}},required:['accountId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input.accountId!=='string'||!find(input.accountId))throw new Error('Unknown accountId');openAccount(input.accountId);return {accountId:input.accountId,opened:true};}}];
 for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}
